CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, email_verified INTEGER NOT NULL DEFAULT 0, email_verified_at INTEGER, last_login_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, device TEXT, created_at INTEGER NOT NULL, last_used INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE user_data (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, k TEXT NOT NULL, v TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (user_id, k));
CREATE TABLE rate_limits (id INTEGER PRIMARY KEY AUTOINCREMENT, bucket TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE TABLE email_codes (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL, code_hash TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, UNIQUE (user_id, purpose));
CREATE TABLE profiles (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name TEXT NOT NULL, avatar_json TEXT, updated_at INTEGER NOT NULL);
CREATE TABLE rooms (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, host_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, mode TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'lobby', surah INTEGER NOT NULL, start_ayah INTEGER NOT NULL, end_ayah INTEGER NOT NULL, max_players INTEGER NOT NULL, lives INTEGER NOT NULL DEFAULT 0, current_ayah INTEGER NOT NULL, turn_user_id INTEGER, attempt INTEGER NOT NULL DEFAULT 1, turn_deadline INTEGER, version INTEGER NOT NULL DEFAULT 1, winner_id INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE room_players (room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, seat INTEGER NOT NULL, lives INTEGER NOT NULL DEFAULT 0, score INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', joined_at INTEGER NOT NULL, PRIMARY KEY (room_id, user_id));
CREATE TABLE room_turns (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, ayah INTEGER NOT NULL, ok INTEGER NOT NULL, similarity INTEGER, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
